      .from('restaurants')
      .select('id, name, address, logo_url, business_hours, slug, aparencia, frete_motoboy, modulo_delivery')
      .eq('custom_domain', dominio)
      .maybeSingle();

    if (!restaurante) throw new NotFoundException('Domínio não configurado');
