        </div>
        {i < total - 1 && (
          <div className={`flex-1 h-0.5 rounded-full ${i < etapa ? 'bg-[#FF441F]' : 'bg-[#E4E4E7] dark:bg-[#3F3F46]'}`} />
        )}
      </React.Fragment>
    ))}
  </div>
);

